INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.125.0',
  '2026-10-29',
  'Checker: пункты списком из текста',
  E'В настройках группы (⚙️) появилась кнопка «⬆️ Импортировать пункты». Открывается поле, в него вставляется список — и по «ОК» каждая строка становится пунктом. Удобно, когда список уже где-то написан: в заметках, в переписке, в письме.\n\nЛишнее срезается само: дефисы и звёздочки в начале строки, нумерация «1.» и «1)», квадратные скобки «[x]» — причём отметка из «[x]» сохраняется, так что готовый чек-лист переносится вместе с галочками. Пустые строки пропускаются, уже имеющиеся пункты остаются на месте, новые дописываются в конец. За один раз принимается до 300 строк.\n\nРаботает и в подгруппах, и в общих списках — пункты меняют и владелец, и участники.',
  E'POST /checker/groups/{id}/items/import с телом {items:[{name,done}]}; разбор строк на клиенте (parseItemLines в transfer.ts поверх общего stripItem — маркеры, нумерация, «[x]»), сервер принимает уже готовый список. Доступ как у остальных операций с пунктами (checkerAccess: владелец корня или участник), предел store.MaxImportItems = 300 строк и 500 символов на пункт.\n\nВ историю списка пишется ОДНА запись («добавил N пунктов из текста») вместо записи на строку: иначе одна вставка затёрла бы всю ленту изменений. Позиции идут через общий createItemUnchecked, то есть дописываются после существующих пунктов с сохранением порядка строк.\n\nЗаголовки «# …» здесь намеренно не разбираются: это добавление в одну открытую группу, а импорт дерева с подгруппами уже есть внизу страницы (POST /checker/groups/import).\n\nПроверено на одноразовой базе: порядок и позиции при дописывании к непустой группе, перенос done из «[x]», отказ на пустом списке и на 301 строке, 404 на чужой группе, одна запись в истории с правильным склонением, разбор строк на смеси маркеров и нумерации.'
);
